Funcion r <- Cuadrado(n Como Entero)
  Definir r Como Entero;
  Escribir "calculando";
  r <- n * n;
FinFuncion

Proceso Principal
  Escribir Cuadrado(3);
FinProceso

SubProceso Avisar()
  Escribir "aviso";
FinSubProceso

Funcion r <- Triple(n Como Entero)
  Definir r Como Entero;
  Avisar();
  r <- n * 3;
FinFuncion

Proceso Principal
  Escribir Triple(3);
FinProceso
